import{_ as i,o,c as n,ag as a}from"./chunks/framework.8tqBsFWt.js";const d=JSON.parse('{"title":"What Winning Looks Like","description":"","frontmatter":{"title":"What Winning Looks Like","order":12},"headers":[],"relativePath":"about/chapters/12-what-winning-looks-like.md","filePath":"about/chapters/12-what-winning-looks-like.md"}'),t={name:"about/chapters/12-what-winning-looks-like.md"};function s(l,e,r,h,u,p){return o(),n("div",null,[...e[0]||(e[0]=[a('<h3 id="_12-what-winning-looks-like" tabindex="-1">12.<br>What Winning Looks Like <a class="header-anchor" href="#_12-what-winning-looks-like" aria-label="Permalink to &quot;12.&lt;br&gt;What Winning Looks Like&quot;">​</a></h3><h4 id="the-vision" tabindex="-1">The Vision <a class="header-anchor" href="#the-vision" aria-label="Permalink to &quot;The Vision&quot;">​</a></h4><p>Let&#39;s get a little bit meta — possible a bit uncomfortable — for a moment. Winning in business is simple but not easy. It&#39;s also a verb, not a noun — there is no winning moment, but a discipline of hard work, making smart bets, and no shortage of good fortune. Once we stop chasing a destination and start behaving in ways that will land us in a better place, we begin being excellent.</p><p>The only comparison worth making is to yourself. Forget comparing yourself, your company, and your people to competitors, it&#39;s a pointless waste of time that gets you nowhere and distracts from the real goal worth achieving, driving towards your own Vision, your own definition of success. There&#39;s no single image of winning except for having spent your time helping others while building an asset for yourself.</p><p>It looks like the owner who:</p><ul><li>Separates do/own/risk</li><li>Has operating values that govern daily decisions</li><li>Trusts the Talent Siphon (celebrates when Level Fours move onto bigger and better things, and is excited to welcome the new incoming Level One hire)</li><li>Uses Bookends to replace surveillance</li><li>Empowers their team through Command by Intent</li><li>Measures LER to help make hard decisions</li><li>Operates a learning company</li></ul><p>Winning in business looks like a business that:</p><ul><li>Generates wealth without consuming the owner</li><li>Survives when a big client leaves</li><li>Adapts when AI shifts what Level One looks like</li><li>Builds succession plans through the Talent Siphon</li></ul><p>Winning in business looks like a team of people who:</p><ul><li>Become excellent through development, not grinding through decades of unenjoyably doing the bare minimum</li></ul><h5 id="you-make-a-choice-daily" tabindex="-1">You Make a Choice Daily <a class="header-anchor" href="#you-make-a-choice-daily" aria-label="Permalink to &quot;You Make a Choice Daily&quot;">​</a></h5><p>You see reality. You can keep the trap or rebuild. The path is clear but not easy. &quot;Change is inevitable; progress is optional,&quot; as John Maxwell said. Your people and your future depend on the decision.</p>',12)])])}const g=i(t,[["render",s]]);export{d as __pageData,g as default};
